const Portrait = (function() {
  const SKIN = ['#faf0e6','#f5e1d0','#fce8d5','#f8e0cc','#fde6d4','#f0d8c8','#fce0d0','#f7dcc8'];
  const HAIR = ['#1e1210','#2a1a14','#1a0e08','#24140e','#1c100a','#20120c'];
  const DRESS = [{m:'#c41e3a',d:'#8b0000',a:'#da5050',e:'#ffd700',n:'红梅'},{m:'#7b2d8e',d:'#4a1858',a:'#a050c0',e:'#e8c0ff',n:'紫霞'},{m:'#1a5276',d:'#0e2f44',a:'#3498db',e:'#a0d4ff',n:'碧海'},{m:'#1a7a5a',d:'#0e4a34',a:'#27ae60',e:'#a0ffc0',n:'翠柳'},{m:'#b8860b',d:'#8b6508',a:'#daa520',e:'#fff4b0',n:'金缕'},{m:'#8b4585',d:'#5a2d5e',a:'#b060a0',e:'#ffc0ff',n:'暮紫'},{m:'#c46030',d:'#8b4020',a:'#e88050',e:'#ffe0c0',n:'霞光'},{m:'#2a6a8a',d:'#1a4060',a:'#40a0c0',e:'#c0f0ff',n:'晴空'},{m:'#a03060',d:'#6a1840',a:'#d05080',e:'#ffc0e0',n:'桃花'},{m:'#6a8040',d:'#4a5a28',a:'#8aa060',e:'#e0f0c0',n:'春草'}];
  const HAIR_STYLES = ['elegant','bun','halfUp','sideBraid'];
  const FLOWER = ['#ffb0c0','#ff90b0','#ffc0d0','#e080a0','#ffa0b8','#f090b0','#ffd0d8','#e87090'];
  const CHAIN = ['#ffd700','#f0c040','#e8b030','#ffc040'];
  const LIPS = ['#c41e3a','#b03060','#d45060','#a02040','#cc4050','#c03050','#d04060','#b03048'];
  const EYE_COLORS = ['#2a1a0a','#1e1210','#3a2010','#1a1008'];
  function h(s){let v=0;for(let i=0;i<s.length;i++)v=((v<<5)-v)+s.charCodeAt(i)|0;return Math.abs(v);}
  function hr(s,a){return a[h(s)%a.length];}
  function hs(s,m){return h(s)%m;}
  function generate(seed){
    const hs2=typeof seed==='string'?seed:''+(Math.random()*1e6|0);
    const sk=hr(hs2,SKIN),hc=hr(hs2,HAIR),dc=DRESS[hs(hs2+'d',DRESS.length)];
    const hs_style=hr(hs2,HAIR_STYLES),fc=hr(hs2,FLOWER),cc=hr(hs2,CHAIN);
    const lc=hr(hs2,LIPS),ec=hr(hs2,EYE_COLORS);
    const hasFlower=hs(hs2+'f',3)>0,hasChain=hs(hs2+'c',4)>0,hasEarring=hs(hs2+'e',2)>0;
    let body=`<rect x="5" y="78" width="90" height="42" rx="3" fill="${dc.d}"/><path d="M8 78 Q50 92 92 78 L92 120 L8 120Z" fill="${dc.m}"/><path d="M38 78 L50 96 L62 78" fill="none" stroke="${dc.a}" stroke-width="1.2" opacity="0.5"/><path d="M20 78 Q50 88 80 78" fill="none" stroke="${dc.a}" stroke-width="0.8" opacity="0.35"/><circle cx="38" cy="88" r="1.2" fill="${dc.e}" opacity="0.5"/><circle cx="50" cy="85" r="1.2" fill="${dc.e}" opacity="0.5"/><circle cx="62" cy="88" r="1.2" fill="${dc.e}" opacity="0.5"/>`;
    let hair='';
    if(hs_style==='elegant'){hair=`<ellipse cx="50" cy="26" rx="30" ry="30" fill="${hc}"/><rect x="22" y="26" width="56" height="52" rx="2" fill="${hc}"/><rect x="25" y="24" width="50" height="3" rx="1.5" fill="${hc}"/><path d="M22 40 Q18 60 24 90" fill="${hc}" opacity="0.7"/><path d="M78 40 Q82 60 76 90" fill="${hc}" opacity="0.7"/>`;}
    else if(hs_style==='bun'){hair=`<ellipse cx="50" cy="24" rx="28" ry="28" fill="${hc}"/><circle cx="50" cy="6" r="14" fill="${hc}"/><rect x="24" y="26" width="52" height="52" rx="2" fill="${hc}"/><path d="M24 40 Q20 60 26 88" fill="${hc}" opacity="0.7"/><path d="M76 40 Q80 60 74 88" fill="${hc}" opacity="0.7"/>`;}
    else if(hs_style==='halfUp'){hair=`<ellipse cx="50" cy="28" rx="30" ry="30" fill="${hc}"/><ellipse cx="50" cy="10" rx="18" ry="10" fill="${hc}"/><rect x="22" y="28" width="56" height="50" rx="2" fill="${hc}"/><path d="M22 42 Q18 65 24 95" fill="${hc}" opacity="0.7"/><path d="M78 42 Q82 65 76 95" fill="${hc}" opacity="0.7"/>`;}
    else{hair=`<ellipse cx="50" cy="28" rx="30" ry="30" fill="${hc}"/><rect x="22" y="28" width="56" height="50" rx="2" fill="${hc}"/><path d="M22 38 Q16 65 22 100" fill="${hc}" opacity="0.7"/><path d="M78 38 Q84 65 78 100" fill="${hc}" opacity="0.7"/><path d="M70 38 Q80 60 76 85" fill="${hc}" opacity="0.5"/>`;}
    let acc='';
    if(hasFlower){const fx=hs(hs2+'fx',2)===0?26:68;acc+=`<ellipse cx="${fx}" cy="14" rx="10" ry="8" fill="${fc}" opacity="0.85"/><ellipse cx="${fx-4}" cy="12" rx="4" ry="3.5" fill="${fc}" opacity="0.7"/><ellipse cx="${fx+4}" cy="12" rx="4" ry="3.5" fill="${fc}" opacity="0.7"/><ellipse cx="${fx}" cy="10" rx="4" ry="3.5" fill="${fc}" opacity="0.7"/><ellipse cx="${fx}" cy="18" rx="4" ry="3.5" fill="${fc}" opacity="0.7"/><circle cx="${fx}" cy="14" r="2" fill="${dc.e}" opacity="0.6"/>`;}
    if(hasChain){acc+=`<path d="M42 4 Q46 8 50 6 Q54 8 58 4" fill="none" stroke="${cc}" stroke-width="0.6" opacity="0.6"/><circle cx="50" cy="12" r="1.5" fill="${fc}" opacity="0.7"/>`;}
    if(hasEarring){acc+=`<circle cx="34" cy="52" r="1.5" fill="${cc}" opacity="0.6"/><line x1="34" y1="53" x2="33" y2="58" stroke="${cc}" stroke-width="0.4" opacity="0.4"/><circle cx="33" cy="59" r="1" fill="${fc}" opacity="0.5"/>`;}
    const brows=`<path d="M36 39 Q42 36 48 38" fill="none" stroke="${hc}" stroke-width="1.3" opacity="0.6"/><path d="M52 38 Q58 36 64 39" fill="none" stroke="${hc}" stroke-width="1.3" opacity="0.6"/>`;
    const eyes=`<ellipse cx="42" cy="46" rx="6" ry="4" fill="white" opacity="0.95"/><ellipse cx="42" cy="46" rx="5.5" ry="3.8" fill="white"/><ellipse cx="42" cy="46.5" rx="3" ry="3" fill="${ec}"/><circle cx="42" cy="46.5" r="1.8" fill="#0a0604"/><circle cx="40.5" cy="45" r="0.9" fill="white" opacity="0.9"/><circle cx="43" cy="47" r="0.4" fill="white" opacity="0.5"/><path d="M36 44 Q42 41 48 44" fill="none" stroke="${hc}" stroke-width="1" opacity="0.6"/><ellipse cx="42" cy="43" rx="5" ry="1.5" fill="${dc.a}" opacity="0.1"/><ellipse cx="58" cy="46" rx="6" ry="4" fill="white" opacity="0.95"/><ellipse cx="58" cy="46" rx="5.5" ry="3.8" fill="white"/><ellipse cx="58" cy="46.5" rx="3" ry="3" fill="${ec}"/><circle cx="58" cy="46.5" r="1.8" fill="#0a0604"/><circle cx="56.5" cy="45" r="0.9" fill="white" opacity="0.9"/><circle cx="59" cy="47" r="0.4" fill="white" opacity="0.5"/><path d="M52 44 Q58 41 64 44" fill="none" stroke="${hc}" stroke-width="1" opacity="0.6"/><ellipse cx="58" cy="43" rx="5" ry="1.5" fill="${dc.a}" opacity="0.1"/>`;
    const nose=`<path d="M49 50 Q50 52 51 50" fill="none" stroke="${sk}" stroke-width="0.6" opacity="0.4"/>`;
    const mouth=`<ellipse cx="50" cy="57" rx="5.5" ry="2.8" fill="${lc}" opacity="0.85"/><ellipse cx="50" cy="56.5" rx="4" ry="1.5" fill="${lc}" opacity="0.3"/><path d="M45 57 Q50 60 55 57" fill="none" stroke="${lc}" stroke-width="0.5" opacity="0.4"/>`;
    const blush=`<ellipse cx="35" cy="53" rx="5" ry="2.5" fill="#ff9999" opacity="0.12"/><ellipse cx="65" cy="53" rx="5" ry="2.5" fill="#ff9999" opacity="0.12"/>`;
    const neck=`<path d="M42 58 Q50 70 58 58" fill="none" stroke="${cc}" stroke-width="0.7" opacity="0.5"/><circle cx="50" cy="70" r="1.5" fill="${dc.e}" opacity="0.5"/>`;
    return `<svg viewBox="0 0 100 120" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="g_${hs2.slice(0,6)}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#fce0d0"/><stop offset="100%" stop-color="#f5d0b8"/></linearGradient></defs><rect width="100" height="120" fill="url(#g_${hs2.slice(0,6)})"/>${body}<path d="M42 58 L42 72 Q50 76 58 72 L58 58" fill="${sk}"/><path d="M38 58 Q30 54 26 60 L38 66Z" fill="${sk}" opacity="0.5"/><path d="M62 58 Q70 54 74 60 L62 66Z" fill="${sk}" opacity="0.5"/>${hair}${acc}${brows}${eyes}${nose}${blush}${mouth}${neck}</svg>`;
  }
  return { generate };
})();
