  function portraitHTML(idx, w, h, src) {
    const r = w<100?8:12;
    let url = src ? src : '';
    if (!url) {
      if (typeof idx === 'string' && idx) url = idx;
      else if (typeof idx === 'number' && idx > 0) url = PORTRAIT_DATA[idx-1] || '';
    }
    if(!url) return `<div style="width:${w}px;height:${h}px;border-radius:${r}px;background:linear-gradient(135deg,#e8c8a0,#d4b090);display:flex;align-items:center;justify-content:center;color:#a08060;font-size:11px;flex-shrink:0;">无图</div>`;
    const onclick = typeof idx === 'string'
      ? ` onclick="Game.showPortraitZoomUrl('${idx}')"`
      : (typeof idx === 'number' ? ` onclick="Game.showPortraitZoom(${idx})"` : '');
    return `<img src="${url}"${onclick} style="width:${w}px;height:${h}px;object-fit:cover;border-radius:${r}px;border:1px solid rgba(139,105,20,0.25);flex-shrink:0;cursor:zoom-in;" loading="lazy" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='flex';"><div style="width:${w}px;height:${h}px;border-radius:${r}px;background:linear-gradient(135deg,#e8c8a0,#d4b090);display:none;align-items:center;justify-content:center;color:#a08060;font-size:11px;flex-shrink:0;">无图</div>`;
  }

  function updateUI() {
    document.getElementById('main-dynasty').textContent = state.dynasty;
    document.getElementById('main-year').textContent = state.dynasty+state.year+'年';
    document.getElementById('main-month').textContent = '第'+state.month+'月';
    document.getElementById('main-treasury').textContent = state.treasury;
    const pips = document.getElementById('main-actions'); pips.innerHTML='';
    for(let i=0;i<5;i++){const p=document.createElement('div');p.className='action-pip'+(i>=state.actionsLeft?' used':'');pips.appendChild(p);}
    const badge = document.getElementById('fab-cold-badge');
    if(state.coldPalaceList.length>0){badge.style.display='flex';badge.textContent=state.coldPalaceList.length;}else{badge.style.display='none';}
    const heirsBadge = document.getElementById('fab-heirs-badge');
    if(state.children.length>0){heirsBadge.style.display='flex';heirsBadge.textContent=state.children.length;}else{heirsBadge.style.display='none';}
    // 坤宁宫按钮显隐
    document.getElementById('palace-alert').style.display=state.pendingEvent?'block':'none';
    const btn=document.getElementById('next-month-btn'); if(btn)btn.classList.toggle('urgent',state.actionsLeft<=0);
    // 选秀提示
    const draftLabel=document.getElementById('draft-countdown');
    if(draftLabel){
      if(state.month===1){
        draftLabel.innerHTML='&#27599;&#24180;1&#26376;&#31168;&#36873;';
        draftLabel.style.display='block';
      } else {
        draftLabel.style.display='none';
      }
    }
    renderBottomBtns('bottom-btns');
    renderMainList();
  }

  function renderBottomBtns(containerId){
    const container=document.getElementById(containerId);if(!container)return;
    let html=`<button class="btn-next" id="next-month-btn" onclick="Game.nextMonth()">&#36827;&#20837;&#19979;&#26376;</button>`;
    html+=`<button class="btn-banquet" onclick="Game.openBanquet()">&#20030;&#21150;&#23476;&#20250;<br><span style="font-size:10px;font-weight:normal;opacity:0.8;">-1&#34892;&#21160;</span></button>`;
    html+=`<button class="btn-bed" onclick="Game.openBed()">&#32763;&#29260;&#20365;&#23517;<br><span style="font-size:10px;font-weight:normal;opacity:0.8;">-1&#34892;&#21160;</span></button>`;
    html+=`<button class="btn-out" onclick="Game.showOut()">&#20986;&#23467;</button>`;
    container.innerHTML=html;
    // Re-apply urgent state
    const btn=document.getElementById('next-month-btn'); if(btn)btn.classList.toggle('urgent',state.actionsLeft<=0);
  }

  // Extract surname from full name (handles compound surnames)
  function getSurname(fullName){
    // Try compound surnames first (longest first)
    const compound=['淳于','钟离','上官','慕容','南宫','东方','西陵'];
    for(const cs of compound){if(fullName.startsWith(cs))return cs;}
    // Fallback: first character
    return fullName.charAt(0);
  }
  // Get display rank name: title+rank or surname+rank
  function getRankName(c){return c.title?c.title+c.rank:getSurname(c.name)+c.rank;}

  function renderMainList() {
    const el = document.getElementById('main-concubine-list');
    if(state.concubines.length===0){el.innerHTML='<div class="empty-state"><div class="empty-icon">&#127963;</div><div class="empty-text">&#21518;&#23467;&#31354;&#26080;&#19968;&#20154;</div><div class="empty-hint">&#31561;&#24453;&#36873;&#31168;&#25110;&#26032;&#20154;&#20837;&#23467;&#8230;&#8230;</div></div>';return;}
    const sorted=[...state.concubines].sort((a,b)=>ri(a.rank)-ri(b.rank));
    let html='';
    sorted.forEach(c=>{
      const rc=RC[c.rank]||'rank-low';
      const isBanned=state.banned[c.id];
      const hp=c.health>=70?'#4caf50':c.health>=40?'#ff9800':'#e55555';
      const rankName=getRankName(c);
      html+=`<div class="concubine-card" onclick="Game.showDetail('${c.id}')">${portraitHTML(c.portraitIdx,80,100,c.princessPortrait)}<div class="concubine-info"><div class="concubine-name"><span class="concubine-rank ${rc}">${rankName}</span><span class="concubine-fullname">${c.name}</span>${isBanned?'<span class="badge badge-banned">&#31105;&#36275;</span>':''}</div><div class="concubine-stats"><span>&#24180;&#40831; <b>${c.age}</b></span><span>&#21183;&#21147; <b style="color:#9060c0;">${c.power}</b></span><span>&#32654;&#35980; <b>${c.beauty}</b></span><span>&#20581;&#24247; <b style="color:${hp}">${c.health}</b></span>${c.pregnant?'<span class="badge badge-pregnant">&#129324; &#26377;&#21916;<span class="badge-pregnant-month">'+c.pregMonth+'&#26376;</span></span>':''}</div></div></div>`;
    });
    el.innerHTML=html;
  }

  function showPage(name){document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));document.getElementById('page-kunning').classList.remove('kunning-bg');const pg=document.getElementById('page-'+name);if(pg)pg.classList.add('active');if(name==='main')updateUI();}

  // Select a punishment option (highlight it, enable confirm button)
  function selectPunishmentOption(idx){
    state._selectedPunish=idx;
    document.querySelectorAll('#event-content .event-option').forEach(function(el,i){
      if(i===idx){
        el.style.borderColor='rgba(200,160,80,0.6)';
        el.style.background='rgba(240,220,200,0.9)';
      } else {
        el.style.borderColor='rgba(200,160,80,0.25)';
        el.style.background='rgba(255,245,230,0.7)';
      }
    });
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.disabled=false;btn.style.opacity='1';}
  }

  // ===== punishment options for investigation events =====
  function showPunishmentOptions(perpId, victimId, eventCtx, eventTitle){
    var perp=state.concubines.find(function(c){return c.id===perpId;});
    var victim=state.concubines.find(function(c){return c.id===victimId;});
    if(!perp){showFeedback('罪臣已不在后宫');state.pendingEvent=null;state._punishmentShown=false;save();updateUI();return;}
    var perpName=perp?perp.name:'罪臣';
    var victimName=victim?victim.name:'受害者';
    state._punishmentShown=true;
    state._selectedPunish=null;
    state._puns={perpId:perp.id,victimId:victim?victim.id:null,perpName,victimName,eventTitle,eventType:eventCtx};
    var html='<div class="event-title">'+eventTitle+'</div><div class="event-desc">查明 <span class="neg">'+perpName+'</span> 确有此行为，请皇上裁决如何处置。</div>';
    html+='<button class="event-option" id="punish-opt-0" onclick="Game.selectPunishmentOption(0)">赐死'+perpName+'</button>';
    html+='<button class="event-option" id="punish-opt-1" onclick="Game.selectPunishmentOption(1)">将'+perpName+'打入冷宫</button>';
    html+='<button class="event-option" id="punish-opt-2" onclick="Game.selectPunishmentOption(2)">杖刑'+perpName+'（健康-30，宠爱-20）</button>';
    html+='<button class="event-option" id="punish-opt-3" onclick="Game.selectPunishmentOption(3)">禁足'+perpName+' 3月（宠爱-10）</button>';
    html+='<button class="event-option" id="punish-opt-4" onclick="Game.selectPunishmentOption(4)">降低'+perpName+'位份（势力-30）</button>';
    document.getElementById('event-content').innerHTML=html;
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认处置';btn.disabled=true;btn.style.opacity='0.5';btn.onclick=function(){Game.confirmPunishment();};btn.style.display='';}
  }

  function confirmPunishment(){
    if(state._selectedPunish===null||!state._puns)return;
    var idx=state._selectedPunish;
    state._selectedPunish=null;
    _punish(idx);
  }

  // Show investigation result with no evidence — requires confirm to dismiss
  function _showNoEvidence(title, desc){
    state._punishmentShown=true;
    state._puns=null;
    state._selectedPunish=null;
    var html='<div class="event-title">'+title+'</div><div class="event-desc">'+desc+'</div>';
    document.getElementById('event-content').innerHTML=html;
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='知道了';btn.disabled=false;btn.style.opacity='1';btn.onclick=function(){Game._dismissNoEvidence();};btn.style.display='';}
  }

  function _dismissNoEvidence(){
    state.pendingEvent=null;
    state._selectedEventOption=null;
    state._punishmentShown=false;
    state._puns=null;
    state._selectedPunish=null;
    var em=document.getElementById('modal-event');
    em.classList.remove('show');
    em.style.display='none';
    closeModal();
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.onclick=function(){Game.confirmEventOption();};}
    setTimeout(function(){em.style.display='';},100);
    save();updateUI();
  }

  function initStart(){
    if(load()&&state.dynasty&&state.concubines){
      // Clean up stale interaction state from previous session
      delete state._bedTarget;delete state._bedPool;delete state._bedFlipping;
      delete state._bedIntercept;delete state._bedInteractTarget;
      delete state._morningTarget;delete state._morningState;
      processBannedDecay();
      save();
      showPage('main');
      updateUI();
      return;
    }
    // 新游戏：直接显示开始页
    showPage('start');
  }

  function showIntro(){
    const overlay=document.getElementById('intro-overlay');
    const video=document.getElementById('intro-video');
    const hint=document.getElementById('intro-hint');
    if(overlay){overlay.classList.add('show');}
    if(video){
      video.currentTime=0;
      video.muted=true;
      video.play().then(function(){
        if(hint)hint.classList.add('hide');
      }).catch(function(){
        if(hint)hint.classList.remove('hide');
      });
      // 点击任意处取消静音（手机端自动播放必为静音，需手动解除）
      overlay.onclick=function(e){
        if(e.target===overlay||e.target===video){
          video.muted=false;
          video.play();
          if(hint)hint.classList.add('hide');
          overlay.onclick=null;
        }
      };
      video.onended=function(){hideIntro();};
    }
  }

  function skipIntro(){
    // 判断当前是新游戏流程还是旧流程
    const overlay=document.getElementById('intro-overlay');
    const video=document.getElementById('intro-video');
    if(video){video.pause();video.currentTime=0;video.onended=null;}
    if(overlay){overlay.classList.remove('show');overlay.onclick=null;}
    // 如果国库弹窗已关闭（新游戏流程），直接进入游戏
    const treasuryModal=document.getElementById('modal-treasury');
    if(treasuryModal&&!treasuryModal.classList.contains('show')){
      if(localStorage.getItem('emperor_music')!=='off'){const audio=document.getElementById('bgm');if(audio)audio.play().catch(()=>{});}
      showPage('main');updateUI();
      setTimeout(()=>triggerDraft(),800);
    } else {
      showPage('start');
    }
  }

  function hideIntro(){
    const overlay=document.getElementById('intro-overlay');
    const video=document.getElementById('intro-video');
    if(video){video.pause();video.currentTime=0;}
    if(overlay){overlay.classList.remove('show');overlay.onclick=null;}
    showPage('start');
  }

  function playIntroForNewGame(){
    const overlay=document.getElementById('intro-overlay');
    const video=document.getElementById('intro-video');
    const hint=document.getElementById('intro-hint');
    if(overlay){overlay.classList.add('show');}
    if(video){
      video.currentTime=0;
      // 用户已点击按钮，浏览器已授权，直接带声音播放
      video.muted=false;
      video.play().then(function(){
        if(hint)hint.classList.add('hide');
      }).catch(function(){
        // 兜底：若仍被拦截，则静音播放，点击屏幕取消静音
        video.muted=true;
        video.play();
        if(hint)hint.classList.remove('hide');
        overlay.onclick=function(e){
          if(e.target===overlay||e.target===video){
            video.muted=false;
            video.play();
            if(hint)hint.classList.add('hide');
            overlay.onclick=null;
          }
        };
      });
      video.onended=function(){
        if(video){video.pause();video.currentTime=0;}
        if(overlay){overlay.classList.remove('show');overlay.onclick=null;video.onended=null;}
        if(localStorage.getItem('emperor_music')!=='off'){const audio=document.getElementById('bgm');if(audio)audio.play().catch(()=>{});}
        showPage('main');updateUI();
        setTimeout(()=>triggerDraft(),800);
      };
    }
  }
  function startNewGame(){
    const v=document.getElementById('dynasty-input').value.trim();
    if(!v){alert('请输入国号！');return;}
    state.dynasty=v;state.treasury=rand(3000,8000);
    document.getElementById('treasury-amount').textContent=state.treasury+' 两';
    var modal=document.getElementById('modal-treasury');
    if(!modal){alert('错误: 找不到modal元素');return;}
    modal.classList.add('show');
  }
  function confirmTreasury(){
    // Reset all game state
    state.year=1;state.month=1;state.actionsLeft=5;
    state.concubines=[];state.coldPalaceList=[];state.banned={};
    state.eventLog=[];state.pendingEvent=null;
    state.eventTriggerRate=60;
    state._draftPool=[];state._draftSelected=[];state._draftIdx=0;
    state._bedTarget=null;state._bedPool=null;state._bedFlipping=false;
    state._banquetSelected=null;state.banquetHeld=false;state.morningTriggered=false;
    state._drafting=false;
    state._punishmentShown=false;
    state._coronationCooldown=null;
    state.honglouLastVisitMonth=0;state.honglouLastVisitYear=0;state.honglouTotalVisits=0;state.honglouContestCooldown=0;
    state.honglouPregnancies=[];state.honglouOutsideFamily=[];state.honglouOldFlames=[];
    state.jiangnanYear=undefined;
    initJiangnan();
    document.getElementById('modal-treasury').classList.remove('show');
    save();
    // 播放开局动画，结束后进入正式游戏
    playIntroForNewGame();
  }
  function processBannedDecay(){for(const id in state.banned){state.banned[id]--;if(state.banned[id]<=0)delete state.banned[id];}}
  function processColdDecay(){state.coldPalaceList=state.coldPalaceList.filter(c=>{c.health=clamp(c.health-10,0,100);c.power=clamp(c.power-5,0,500);if(c.health<=0){logEvent('&#30149;&#36893;&#33268;&#27515;',c.rank+c.name+'&#22312;&#20919;&#23467;&#20013;&#30149;&#36893;');showFeedback('<span class="neg">'+c.name+'</span> &#22312;&#20919;&#23467;&#20013;&#20581;&#24247;&#24402;&#38646;&#65292;&#30149;&#36893;');return false;}return true;});}

  function consumeAction(){state.actionsLeft--;const used=5-state.actionsLeft;if(state.actionsLeft<=0){setTimeout(()=>{if(!state.pendingEvent){showFeedback('&#26412;&#26376;&#34892;&#21160;&#24050;&#29992;&#23436;&#65292;&#33258;&#21160;&#36827;&#20837;&#19979;&#26376;&#65281;');setTimeout(()=>nextMonth(),1500);}},500);}else{setTimeout(()=>{if(state.concubines.length>=2&&!state.pendingEvent&&!state.eventTriggeredThisMonth){const targetAction=state.monthEventAction;if(used>=targetAction){triggerPalaceEvent();state.eventTriggeredThisMonth=true;}}if(!state.pendingEvent){tryTriggerMorning();}},500);}}

  function nextMonth(){
    if(state.pendingEvent){showFeedback('&#35831;&#20808;&#22788;&#29702;&#21518;&#23467;&#24322;&#21160;&#20107;&#20214;&#65281;');return;}
    // 月份切换转场
    var overlay=document.getElementById('month-transition');
    if(overlay){
      overlay.style.display='block';
      overlay.style.opacity='0';
      requestAnimationFrame(function(){
        overlay.style.opacity='1';
        setTimeout(function(){
          doNextMonth();
          setTimeout(function(){
            overlay.style.opacity='0';
            setTimeout(function(){ overlay.style.display='none'; },600);
          },100);
        },600);
      });
    } else {
      doNextMonth();
    }
  }
  function doNextMonth(){
    state.month++;if(state.month>12){state.month=1;state.year++;state.concubines.forEach(c=>{c.age++;});state.coldPalaceList.forEach(c=>{c.age++;});state.children.forEach(ch=>{ch.age++;if(ch.age>=6){ch.talent=clamp(ch.talent+rand(2,5),0,100);ch.virtue=clamp(ch.virtue+rand(1,3),0,100);}if(ch.age>=12){ch.martial=clamp(ch.martial+rand(1,3),0,100);ch.prestige=clamp(ch.prestige+rand(1,2),0,100);}});state.draftTriggeredThisYear=false;}
    state.treasury+=10000;state.actionsLeft=5;state.banquetHeld=false;state.morningTriggered=false;state.eventTriggeredThisMonth=false;state.monthEventAction=Math.floor(Math.random()*3)+1;
    processBannedDecay();processColdDecay();processPregnancy();processChildrenHealth();processStressDecay();processGrudge();save();updateUI();checkStressBreakdownEvent();
    // 醉红楼认亲剧情判定
    checkHonglouReunion();
    // 西域公主来访事件：首年第9月触发
    if(state.year===1&&state.month===9&&!state.princessEventTriggered){
      state.princessEventTriggered=true;
      setTimeout(()=>triggerPrincessEvent(),400);
      return;
    }
    // 选秀：每年1月触发一次
    if(state.month===1&&!state.draftTriggeredThisYear){
      state.draftTriggeredThisYear=true;
      setTimeout(()=>triggerDraft(),300);
    }
  }

  function processStressDecay(){
    state.concubines.forEach(c=>{
      if(c.stress!==undefined&&c.stress>0){
        c.stress=clamp(c.stress-3,0,100);
      }
      // 每月国库支出（孤儿抚养）
      if(state.children){
        state.children.forEach(ch=>{
          if(ch.monthlyCost>0){
            state.treasury-=ch.monthlyCost;
            ch.orphanMonth++;
            // 满12年后自动停止月费
            if(ch.orphanMonth>=144){ch.monthlyCost=0;ch.isOrphan=false;}
          }
        });
      }
    });
  }

  // ===== 子嗣幼年夭折判定 =====
  function processChildrenHealth(){
    state.children=state.children.filter(ch=>{
      if(ch.age>=0&&ch.age<=5){
        let rate=0.08;
        if(ch.health<50)rate=0.15;
        if(ch.isOrphan)rate=Math.max(rate,0.12);
        if(Math.random()<rate){
          const mother=state.concubines.find(c=>c.id===ch.motherId);
          if(mother){
            mother.favor=clamp(mother.favor-50,0,2200);mother.health=clamp(mother.health-15,0,100);
            mother.power=clamp(mother.power-15,0,500);mother.stress=clamp((mother.stress||0)+15,0,100);
            const pn=mother.personality?mother.personality.name:'';
            if((pn==='狠戾果决'||pn==='偏执痴迷')&&Math.random()<0.30){
              const targets=state.concubines.filter(c=>c.id!==mother.id&&c.rank!=='皇后');
              if(targets.length>0)mother.grudge={targetId:pick(targets).id,intensity:50};
            }
          }
          logEvent('幼子夭折',ch.name+'夭折');
          setTimeout(()=>showFeedback('<span class="neg">'+ch.name+'</span> 不幸夭折'+(mother?'<br>生母 '+mother.name+' 伤心欲绝':'')),200);
          return false;
        }
      }
      return true;
    });
  }

  // ===== 夺宠之恨月度处理 =====
  function processGrudge(){
    const concs=state.concubines.filter(c=>c.grudge&&c.grudge.targetId);
    concs.forEach(c=>{
      // 每月怀恨值衰减
      c.grudge.intensity=clamp(c.grudge.intensity-3,0,100);
      if(c.grudge.intensity<=0){c.grudge=null;return;}
      // 怀恨值>30时，有概率触发夺宠之恨事件
      if(c.grudge.intensity>30&&Math.random()<0.15){
        const target=state.concubines.find(x=>x.id===c.grudge.targetId);
        if(!target)return;
        const pname=c.personality?c.personality.name:'default';
        const weights=PERSONALITY_EVENT_WEIGHTS['夺宠之恨']||{};
        const w=weights[pname]||weights['default']||1.0;
        if(Math.random()<(w/3)){
          const schemes=pick(['暗中搜集把柄','买通对方宫中的太监','在皇上面前说对方坏话','散布对方的谣言']);
          state.pendingEvent={
            title:'【夺宠之恨】',
            desc:`深夜，太监来报：${c.rank}${c.name}近日夜不能寐，暗中${schemes}。宫人私下议论，说她眼中满是恨意，似在筹划什么。`,
            options:[
              {text:'🔍 暗中调查（国库-300）',effect(){if(state.treasury<300){showFeedback('国库不足！');state.pendingEvent=null;save();updateUI();return;}state.treasury-=300;if(Math.random()<0.5){c.favor=clamp(c.favor-15,0,2200);c.grudge=null;logEvent('夺宠之恨','查实'+c.name);save();updateUI();showFeedback(`查明真相！<span class="neg">${c.name}</span> 宠爱 <span class="neg">-15</span>，怀恨消解`);}else{c.favor=clamp(c.favor+5,0,2200);if(c.grudge)c.grudge.intensity=clamp(c.grudge.intensity+10,0,100);logEvent('夺宠之恨','查无实据');save();updateUI();showFeedback(`查无实据<br>${c.name} 宠爱 <span class="pos">+5</span>`);}}},
              {text:'🗣 召来问话（'+c.name+'压力+20）',effect(){c.favor=clamp(c.favor-10,0,2200);updateStress(c,20);if(c.grudge)c.grudge.intensity=clamp(c.grudge.intensity-10,0,100);logEvent('夺宠之恨','问话'+c.name);save();updateUI();showFeedback(`${c.name} 被召来问话<br>宠爱 <span class="neg">-10</span>，压力 <span class="neg">+20</span>`);}},
              {text:' 装作不知（怀恨+10）',effect(){if(c.grudge)c.grudge.intensity=clamp(c.grudge.intensity+10,0,100);logEvent('夺宠之恨','放任'+c.name);save();updateUI();showFeedback(`皇上装作不知<br>${c.name} 怀恨加深`);}},
            ]
          };
          state._selectedEventOption=0;
          showEventModal();
          return;
        }
      }
    });
  }

  function checkStressBreakdownEvent(){
    if(state.pendingEvent)return;
    const breakdown=checkStressBreakdown();
    if(breakdown){
      state.pendingEvent=breakdown;
      state._selectedEventOption=0;
      showEventModal();
    }
  }


  function processPregnancy(){
    const births=[];
    state.concubines.forEach(c=>{
      if(!c.pregnant)return;
      c.pregMonth++;
      // 第3-9个月有自然滑胎风险
      if(c.pregMonth>=3&&c.pregMonth<=9){
        let rate=0.15;
        if(c.health<50)rate=0.25;
        if(c.power<20)rate=Math.max(rate,0.20);
        if(Math.random()<rate){
          c.pregnant=false;c.pregMonth=0;
          c.health=clamp(c.health-15,0,100);c.favor=clamp(c.favor-10,0,2200);c.power=clamp(c.power-5,0,500);
          logEvent('自然滑胎',c.name+'不幸滑胎');triggerMiscarriageAftermath(c);
          setTimeout(()=>showFeedback('<span class="neg">'+c.name+'</span> 不幸滑胎<br>健康<span class="neg">-15</span>，宠爱<span class="neg">-10</span>'),300);
          return;
        }
      }
      // 怀孕每月增加宠爱和势力，但累计不超过生子奖励（皇子:宠爱100/权力20，公主:宠爱60/权力12）
      const favorInc=c.pregMonth>=9?0:rand(3,6);
      const powerInc=c.pregMonth>=9?0:rand(1,2);
      if(favorInc>0)c.favor=clamp(c.favor+favorInc,0,2200);
      if(powerInc>0)c.power=clamp(c.power+powerInc,0,500);
      c.health=clamp(c.health-2,0,100);
      if(c.pregMonth>=10){
        const isBoy=Math.random()<0.5;
        births.push({concubine:c,childType:isBoy?'&#30343;&#23376;':'&#20844;&#20027;'});
        c.pregnant=false;c.pregMonth=0;
      }
    });
    if(births.length>0){setTimeout(()=>showBirthResult(births),300);}
  }

  function triggerMiscarriageAftermath(c){
    if(Math.random()<0.30){c._fertilityPenalty=3;logEvent('流产后遗症',c.name+'体虚难孕');}
  }

