  function findC(id){return state.concubines.find(x=>x.id===id);}
  function checkDeath(c){if(!c||c.health>0)return;if(c.rank==='皇后')return;var kids=state.children.filter(ch=>ch.motherId===c.id&&(ch.adoptiveMotherId===null||ch.adoptiveMotherId===undefined));if(kids.length>0){triggerOrphanAdoption(c,kids);}state.concubines=state.concubines.filter(x=>x.id!==c.id);logEvent('&#30149;&#36893;',c.rank+c.name+'&#20581;&#24247;&#24402;&#38646;&#65292;&#30149;&#36893;');save();updateUI();showFeedback('<span class="neg">'+c.name+'</span> &#20581;&#24247;&#24402;&#38646;&#65292;&#30149;&#36893;');}
  function canAct(){if(state.actionsLeft<=0){showFeedback('&#26412;&#26376;&#34892;&#21160;&#27425;&#25968;&#24050;&#29992;&#23436;&#65281;<br>&#35831;&#28857;&#20987;&#12300;&#36827;&#20837;&#19979;&#26376;&#12301;&#21047;&#26032;&#12290;');return false;}return true;}

  function actionFavor(id){
    if(!canAct())return;const c=findC(id);if(!c)return;
    if(state.treasury<200){showFeedback('&#22269;&#24211;&#38134;&#20004;&#19981;&#36275;&#65281;');return;}
    state.treasury-=200;c.favor=clamp(c.favor+15,0,2200);c.power=clamp(c.power+2,0,500);
    triggerFavorBackground(c);
    const rc=checkRankChange(c);
    let pregChance=0.25;if(c._fertilityPenalty&&c._fertilityPenalty>0){pregChance=0.125;c._fertilityPenalty--;}
    if(!c.pregnant&&c.rank!=='皇后'&&Math.random()<pregChance){c.pregnant=true;c.pregMonth=1;c.power=clamp(c.power+8,0,500);setTimeout(()=>showPregnancyAlert(c.name,8),500);}
    consumeAction();save();updateUI();
    let msg='&#23456;&#24184;&#20102; <span class="pos">'+c.name+'</span><br>&#23456;&#29233; <span class="pos">+15</span>&#65292;&#21183;&#21147; <span class="pos">+2</span><br>&#22269;&#24211; <span class="neg">-200</span>&#20004;<br>&#34892;&#21160; <span class="neg">-1</span>';
    if(rc){msg+='<br>&#21183;&#21147;&#28287;&#36275;&#65292;<span class="pos">'+c.name+' &#26187;&#21319;&#20026; '+rc.rank+'</span>';}
    showFeedback(msg);
    showDetail(id);
  }

