  function tryTriggerMorning(){
    if(state.morningTriggered)return;
    if(state.concubines.length===0)return;
    if(state.pendingEvent)return;
    if(state._bedTarget)return;
    if(state.eventResolvedPending)return;
    if(Math.random()>0.35)return;
    state.morningTriggered=true;
    const c=state.concubines[Math.floor(Math.random()*state.concubines.length)];
    startMorning(c);
  }

  function startMorning(c){
    tryOpenModal(()=>{
    state._morningConcubine=c.id;
    state._morningRound=1;
    state._morningFavorChange=0;
    const dlgSet=MORNING_DIALOGUES[c.personality.name]||MORNING_DIALOGUES['端庄'];
    const dlg=dlgSet[Math.floor(Math.random()*dlgSet.length)];
    state._morningDialogue=dlg;
    state._morningOptions=dlg.opts;
    renderMorningDialogue(c);
  });}

  function renderMorningDialogue(c){
    const dlg=state._morningDialogue;
    const opts=state._morningOptions;
    const el=document.getElementById('morning-content');
    let html='<div style="padding:8px;">';
    html+=`<div style="text-align:center;margin-bottom:12px;">${portraitHTML(c.portraitIdx,60,76,c.princessPortrait)}
      <div style="font-size:15px;font-weight:bold;color:#c49030;margin-top:4px;">${c.rank} ${c.name}</div>
      <div style="font-size:11px;color:#9060c0;">${c.personality.name}</div></div>`;
    if(state._morningRound===1){
      html+=`<div style="background:rgba(255,245,230,0.8);border:1px solid rgba(200,160,80,0.2);border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:14px;color:#5a3e28;line-height:1.6;">${dlg.r1c}</div>`;
    } else {
      html+=`<div style="background:rgba(255,245,230,0.8);border:1px solid rgba(200,160,80,0.2);border-radius:12px;padding:12px 16px;margin-bottom:14px;font-size:14px;color:#5a3e28;line-height:1.6;">${state._morningR2c}</div>`;
    }
    html+='<div style="display:flex;flex-direction:column;gap:6px;">';
    opts.forEach((o,i)=>{
      html+=`<button class="btn-option" onclick="Game.morningReply(${i})" style="text-align:left;padding:10px 14px;border:1px solid rgba(200,160,80,0.25);border-radius:10px;background:rgba(255,245,230,0.6);color:#5a3e28;font-size:13px;font-family:inherit;cursor:pointer;">${o.t}</button>`;
    });
    html+='</div></div>';
    el.innerHTML=html;
    document.querySelector('#modal-morning .modal-header').textContent='妃 子 请 安';
    document.getElementById('modal-morning').classList.add('show');
  }

  function morningReply(idx){
    const c=state.concubines.find(x=>x.id===state._morningConcubine);
    if(!c){
      document.getElementById('modal-morning').classList.remove('show');
      delete state._morningConcubine;delete state._morningRound;delete state._morningDialogue;
      delete state._morningOptions;delete state._morningFavorChange;delete state._morningR2c;
      closeModal();
      showFeedback('请安已结束');
      return;
    }
    const opts=state._morningOptions;
    const chosen=opts[idx];if(!chosen)return;
    state._morningFavorChange+=chosen.f;

    if(state._morningRound===1){
      state._morningRound=2;
      const r2Lines=MORNING_R2_LINES[c.personality.name]||MORNING_R2_LINES['端庄'];
      state._morningR2c=r2Lines[Math.floor(Math.random()*r2Lines.length)];
      state._morningOptions=[
        {t:'朕明白了',r:'皇上圣明。',f:3},
        {t:'你说得对',r:'谢皇上认可。',f:6},
        {t:'朕自有主张',r:'是，臣妾多嘴了。',f:-2},
      ];
      renderMorningDialogue(c);
    } else {
      const favorChange=state._morningFavorChange;
      c.favor=clamp(c.favor+favorChange,0,2200);
      const powerDelta=favorChange>0?Math.ceil(favorChange/4):Math.floor(favorChange/4);
      c.power=clamp(c.power+powerDelta,0,500);
      const rc=checkRankChange(c);
      logEvent('请安',`${c.name} 请安对话`);
      document.getElementById('modal-morning').classList.remove('show');
      delete state._morningConcubine;delete state._morningRound;delete state._morningDialogue;
      delete state._morningOptions;delete state._morningFavorChange;delete state._morningR2c;
      closeModal();
      save();updateUI();
      let msg=`${c.name} 请安完毕<br>宠爱 ${favorChange>0?'<span class="pos">+'+favorChange+'</span>':'<span class="neg">'+favorChange+'</span>'}&#65292;&#21183;&#21147; ${powerDelta>0?'<span class="pos">+'+powerDelta+'</span>':'<span class="neg">'+powerDelta+'</span>'}`;
      if(rc){msg+=`<br><span class="pos">${c.name} 晋升为 ${rc.rank}</span>`;}
      showFeedback(msg);
    }
  }

