  // ===== 宫殿事件生成 =====
  function genSingle(c){
    return{title:'【'+c.rank+c.name+'】',desc:`${c.rank}${c.name}近日心情不佳，独自一人御花园中赏花落泪。`,options:[
      {text:'💝 前去安慰（国库-500，宠爱+10）',effect(){if(state.treasury<500){showFeedback('国库不足！');state.pendingEvent=null;save();updateUI();return;}state.treasury-=500;c.favor=clamp(c.favor+10,0,2200);c.power=clamp(c.power+3,0,500);logEvent('独处','安慰'+c.name);save();updateUI();showFeedback(`安慰 <span class="pos">${c.name}</span><br>宠爱 <span class="pos">+10</span>&#65292;&#21183;&#21147; <span class="pos">+3</span><br>国库 <span class="neg">-500</span>`);}},
      {text:'📝 赐诗一首（宠爱+5）',effect(){c.favor=clamp(c.favor+5,0,2200);c.power=clamp(c.power+2,0,500);logEvent('独处','赐诗'+c.name);save();updateUI();showFeedback(`赐诗 <span class="pos">${c.name}</span><br>宠爱 <span class="pos">+5</span>&#65292;&#21183;&#21147; <span class="pos">+2</span>`);}},
      {text:' 不必理会（宠爱-5）',effect(){c.favor=clamp(c.favor-5,0,2200);c.power=clamp(c.power-3,0,500);logEvent('独处','冷落'+c.name);save();updateUI();showFeedback(`${c.name} 宠爱 <span class="neg">-5</span>&#65292;&#21183;&#21147; <span class="neg">-3</span>`);}},
      {text:'🔒 打入冷宫',effect(){state.concubines=state.concubines.filter(x=>x.id!==c.id);c.health=clamp(c.health-20,0,100);c.power=clamp(c.power-20,0,500);state.coldPalaceList.push(c);logEvent('独处','打入冷宫'+c.name);save();updateUI();showFeedback(`<span class="neg">${c.name}</span> 被打入冷宫`);}},
      {text:'☠ 赐死',effect(){showExecutionSelect(c.id,false,false);}},
    ]};
  }

  function genPregnancyEvent(){
    const preg=state.concubines.filter(c=>c.pregnant&&c.pregMonth>=2&&c.pregMonth<=9);
    if(preg.length===0)return null;
    const c=pick(preg);
    const others=state.concubines.filter(x=>x.id!==c.id);
    if(others.length<1)return null;
    const rival=pickWeighted(others,'孕期风波','perpetrator');
    return{title:'【孕期风波】',desc:`${c.rank}${c.name}已有${c.pregMonth}个月身孕，近日${rival.rank}${rival.name}屡屡挑衅，${c.name}受惊后腹痛不安，太医说恐有滑胎之险。`,options:[
      {text:'🏥 精心照料（国库-1200，'+c.name+'健康+10，安心养胎）',effect(){if(state.treasury<1200){showFeedback('国库不足！');state.pendingEvent=null;save();updateUI();return;}state.treasury-=1200;c.health=clamp(c.health+10,0,100);rival.favor=clamp(rival.favor-10,0,2200);rival.power=clamp(rival.power-5,0,500);logEvent('孕期风波','精心照料');save();updateUI();showFeedback(`精心照料 <span class="pos">${c.name}</span><br>健康 <span class="pos">+10</span>，安心养胎<br>${rival.name} 宠爱 <span class="neg">-10</span>&#65292;&#21183;&#21147; <span class="neg">-5</span><br>国库 <span class="neg">-1200</span>`);}},
      {text:'🔒 禁足'+rival.name+'（'+rival.name+'禁足1月，'+c.name+'安心）',effect(){state.banned[rival.id]=1;c.health=clamp(c.health+5,0,100);logEvent('孕期风波','禁足');save();updateUI();showFeedback(`禁足 <span class="neg">${rival.name}</span> 1月<br>${c.name} 健康 <span class="pos">+5</span>，安心养胎`);}},
      {text:' 顺其自然（'+c.name+'有55%概率流产）',effect(){if(Math.random()<0.55){c.pregnant=false;c.pregMonth=0;c.health=clamp(c.health-20,0,100);c.power=clamp(c.power-10,0,500);logEvent('孕期风波',c.name+'流产');triggerMiscarriageAftermath(c);save();updateUI();showFeedback('<span class="neg">'+c.name+' 不幸流产</span><br>健康<span class="neg">-20</span>，势力<span class="neg">-10</span>');}else{c.health=clamp(c.health-5,0,100);logEvent('孕期风波','母子平安');save();updateUI();showFeedback(c.name+' 有惊无险<br>健康<span class="neg">-5</span>，母子平安');}}},
      {text:'☠ 赐死'+rival.name,effect(){state._executeVictimInfo={victimId:c.id,victimName:c.name,favorInc:15,healthInc:10};showExecutionSelect(rival.id,false,false,{eventType:'孕期风波',vars:{perpName:rival.name,victimName:c.name,year:state.year,month:state.month,victimPregMonth:c.pregMonth}});}}
    ]};
  }

  function genJealousy(con){
    const a=pickWeighted(con,'争风吃醋','perpetrator');
    let b=null;
    if(a.favors){const hostile=con.filter(c=>c.id!==a.id&&a.favors[c.id]<-15);if(hostile.length>0)b=pick(hostile);}
    if(!b)b=pick(con.filter(c=>c.id!==a.id));
    return{title:'【争风吃醋】',desc:`${a.rank}${a.name}与${b.rank}${b.name}因皇上近日宠爱一事心生嫌隙，今日在御花园中相遇，言语交锋，闹得不可开交。`,options:[
      {text:'⚖ 各打五十大板（两人各-5宠爱）',effect(){a.favor=clamp(a.favor-5,0,2200);b.favor=clamp(b.favor-5,0,2200);a.power=clamp(a.power-3,0,500);b.power=clamp(b.power-3,0,500);updateStress(a,5);updateStress(b,5);if(!a.favors)a.favors={};if(!b.favors)b.favors={};a.favors[b.id]=(a.favors[b.id]||0)-5;b.favors[a.id]=(b.favors[a.id]||0)-5;logEvent('争宠','各打五十大板');save();updateUI();showFeedback(`两人各 <span class="neg">-5</span> 宠爱&#65292;&#21183;&#21147; <span class="neg">-3</span>`);}},
      {text:'💝 偏袒'+a.name+'（'+a.name+'宠爱+10，'+b.name+'-10）',effect(){a.favor=clamp(a.favor+10,0,2200);b.favor=clamp(b.favor-10,0,2200);a.power=clamp(a.power+3,0,500);b.power=clamp(b.power-5,0,500);updateStress(a,-8);updateStress(b,15);if(!a.favors)a.favors={};if(!b.favors)b.favors={};a.favors[b.id]=(a.favors[b.id]||0)+5;b.favors[a.id]=(b.favors[a.id]||0)-15;logEvent('争宠','偏袒'+a.name);save();updateUI();showFeedback(`${a.name} <span class="pos">+10</span>&#65292;&#21183;&#21147; <span class="pos">+3</span>，${b.name} <span class="neg">-10</span>&#65292;&#21183;&#21147; <span class="neg">-5</span>`);}},
      {text:'💝 偏袒'+b.name+'（'+b.name+'宠爱+10，'+a.name+'-10）',effect(){b.favor=clamp(b.favor+10,0,2200);a.favor=clamp(a.favor-10,0,2200);b.power=clamp(b.power+3,0,500);a.power=clamp(a.power-5,0,500);updateStress(b,-8);updateStress(a,15);if(!a.favors)a.favors={};if(!b.favors)b.favors={};b.favors[a.id]=(b.favors[a.id]||0)+5;a.favors[b.id]=(a.favors[b.id]||0)-15;logEvent('争宠','偏袒'+b.name);save();updateUI();showFeedback(`${b.name} <span class="pos">+10</span>&#65292;&#21183;&#21147; <span class="pos">+3</span>，${a.name} <span class="neg">-10</span>&#65292;&#21183;&#21147; <span class="neg">-5</span>`);}},
      {text:'🔒 都禁足1月（平息事端）',effect(){state.banned[a.id]=1;state.banned[b.id]=1;updateStress(a,8);updateStress(b,8);logEvent('争宠','都禁足');save();updateUI();showFeedback(`${a.name}、${b.name} 各禁足 1月`);}},
      {text:'☠ 赐死'+a.name,effect(){logBehavior(a,'争风吃醋','heavy',true);updateStress(a,30);state._executeVictimInfo={victimId:b.id,victimName:b.name,favorInc:10};showExecutionSelect(a.id,false,false);}},
      {text:'🔒 将'+b.name+'打入冷宫',effect(){logBehavior(b,'争风吃醋','heavy',true);updateStress(b,30);state.concubines=state.concubines.filter(x=>x.id!==b.id);b.health=clamp(b.health-20,0,100);state.coldPalaceList.push(b);logEvent('争宠','打入冷宫'+b.name);save();updateUI();showFeedback(`<span class="neg">${b.name}</span> 被打入冷宫`);}},
    ]};
  }

  function _punish(idx){
    console.log('_punish called with idx:', idx, 'puns:', state._puns);
    const p=state._puns;
    if(!p){console.log('_punish: no puns data');return;}
    const perp=state.concubines.find(c=>c.id===p.perpId);
    const victim=p.victimId?state.concubines.find(c=>c.id===p.victimId):null;
    const perpName=p.perpName;
    const victimName=p.victimName;
    const eventTitle=p.eventTitle;
    state._puns=null;
    state.pendingEvent=null;
    state._punishmentShown=false;
    state._selectedPunish=null;
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.onclick=function(){Game.confirmEventOption();};}
    // Force hide the event modal immediately
    const eventModal=document.getElementById('modal-event');
    eventModal.classList.remove('show');
    eventModal.style.display='none';
    if(!perp){closeModal();setTimeout(()=>{eventModal.style.display='';},100);save();updateUI();return;}
    if(idx===0){
      logBehavior(perp,p.eventType||'unknown','heavy',true);
      updateStress(perp,30);
      state._executeVictimInfo={victimId:p.victimId,victimName:victimName};
      showExecutionSelect(perp.id,false,false,{eventType:p.eventType||'',vars:{perpName:perpName,victimName:victimName||'',year:state.year,month:state.month}});
      return;
    } else if(idx===1){
      logBehavior(perp,p.eventType||'unknown','heavy',true);
      updateStress(perp,30);
      if(victim){updateStress(victim,-15);}
      state.concubines=state.concubines.filter(x=>x.id!==perp.id);
      perp.health=clamp(perp.health-20,0,100);
      state.coldPalaceList.push(perp);
      logEvent(eventTitle,'打入冷宫'+perpName);
      if(victim){victim.favor=clamp(victim.favor+10,0,2200);victim.health=clamp(victim.health+5,0,100);}
      closeModal();save();updateUI();
      showFeedback(`${perpName} 被打入冷宫<br>${victimName} 宠爱 <span class="pos">+10</span>，健康 <span class="pos">+5</span>`);
    } else if(idx===2){
      logBehavior(perp,p.eventType||'unknown','medium',true);
      updateStress(perp,20);
      if(victim){updateStress(victim,-10);}
      perp.health=clamp(perp.health-30,0,100);
      perp.favor=clamp(perp.favor-20,0,2200);
      perp.power=clamp(perp.power-15,0,500);
      logEvent(eventTitle,'杖刑'+perpName);
      if(victim){victim.favor=clamp(victim.favor+5,0,2200);victim.health=clamp(victim.health+5,0,100);}
      closeModal();save();updateUI();
      showFeedback(`${perpName} 受杖刑<br>健康 <span class="neg">-30</span>，宠爱 <span class="neg">-20</span>&#65292;&#21183;&#21147; <span class="neg">-15</span><br>${victimName} 宠爱 <span class="pos">+5</span>，健康 <span class="pos">+5</span>`);
    } else if(idx===3){
      logBehavior(perp,p.eventType||'unknown','light',true);
      updateStress(perp,10);
      if(victim){updateStress(victim,-5);}
      perp.favor=clamp(perp.favor-10,0,2200);
      state.banned[perp.id]=3;
      logEvent(eventTitle,'禁足'+perpName);
      if(victim){victim.favor=clamp(victim.favor+5,0,2200);}
      closeModal();save();updateUI();
      showFeedback(`${perpName} 禁足 3月<br>宠爱 <span class="neg">-10</span><br>${victimName} 宠爱 <span class="pos">+5</span>`);
    } else if(idx===4){
      logBehavior(perp,p.eventType||'unknown','medium',true);
      updateStress(perp,20);
      if(victim){updateStress(victim,-8);}
      if(perp&&perp.rank!=='官女子'){
        let newR=perp.rank;
        const rd2=rd(newR);
        if(rd2&&rd2!==newR)newR=rd2;
        perp.rank=newR;
      }
      perp.power=clamp(perp.power-30,0,500);
      perp.favor=clamp(perp.favor-15,0,2200);
      const rc=checkRankChange(perp);
      logEvent(eventTitle,'降低位份'+perpName);
      if(victim){victim.favor=clamp(victim.favor+5,0,2200);victim.power=clamp(victim.power+5,0,500);}
      closeModal();save();updateUI();
      let msg=`${perpName} 位份降为 <span class="neg">${perp.rank}</span><br>势力 <span class="neg">-30</span>，宠爱 <span class="neg">-15</span>`;
      if(rc&&rc.type==='demote')msg+=`<br>因势力不足，进一步降为 <span class="neg">${rc.rank}</span>`;
      msg+=`<br>${victimName} 宠爱 <span class="pos">+5</span>&#65292;&#21183;&#21147; <span class="pos">+5</span>`;
      showFeedback(msg);
    }
    // 更新关系网
    if(perp&&victim){
      if(!perp.favors)perp.favors={};
      if(!victim.favors)victim.favors={};
      perp.favors[victim.id]=(perp.favors[victim.id]||0)-15;
      victim.favors[perp.id]=(victim.favors[perp.id]||0)-30;
    }
    setTimeout(()=>{eventModal.style.display='';},100);
  }


  function _dismissEvent(){
    state.pendingEvent=null;
    state._selectedEventOption=null;
    state._punishmentShown=false;
    state._puns=null;
    state._selectedPunish=null;
    const em=document.getElementById('modal-event');
    em.classList.remove('show');
    em.style.display='none';
    closeModal();
    var btn=document.getElementById('event-confirm-btn');
    if(btn){btn.textContent='确认';btn.onclick=function(){Game.confirmEventOption();};}
    setTimeout(()=>{em.style.display='';},100);
    save();updateUI();
  }

