  // ===== 初始化 =====
  function init(){
    try{
      load();
      updateUI();
      initStart();
      // Restore music preference (default ON)
      if(localStorage.getItem('emperor_music')!=='off'){
        const audio=document.getElementById('bgm');
        if(audio)audio.play().catch(()=>{});
      }
      const ti=document.getElementById('title-input');
      if(ti) ti.addEventListener('input', function(){
        const c=state.concubines.find(x=>x.id===state._titleTarget);
        if(c) updateTitlePreview(c);
      });
    }catch(e){
      console.error('Init error:', e);
      // Emergency reset - clear everything
      try{localStorage.removeItem('emperor_game');}catch(e){}
      state={dynasty:'',treasury:0,year:1,month:1,actionsLeft:5,concubines:[],coldPalaceList:[],banned:{},eventLog:[],pendingEvent:null,eventTriggerRate:60,nextDraftIn:3,children:[]};
      updateUI();
      initStart();
    }
  }

