  function makeBeautyCard(b,extraBtns){
    var isQueen=b.isFlowerQueen?'is-queen':'';
    var isOld=b.isReunion?'is-old':'';
    var barW=Math.round(b.beauty);
    var favorClr=getFavorColor(b.favor);
    var favorNm=getFavorName(b.favor);
    var html='<div class="hl-beauty-card '+isQueen+' '+isOld+'" onclick="Game.enterHonglouRoom(\''+b.id+'\')">';
    html+='<div class="hl-beauty-portrait">'+portraitHL(b,50,65)+'</div>';
    html+='<div class="hl-beauty-info">';
    html+='<div class="hl-beauty-name-row">';
    html+='<span class="hl-beauty-name">'+b.name+'</span>';
    if(b.isFlowerQueen)html+='<span class="hl-beauty-tag hl-beauty-tag-queen">花魁</span>';
    if(b.isReunion)html+='<span class="hl-beauty-tag hl-beauty-tag-old">旧识</span>';
    html+='</div>';
    html+='<div class="hl-beauty-sub">'+b.age+'岁 · '+b.typeName+' · '+b.trait+'</div>';
    html+='<div class="hl-beauty-bar-wrap"><span class="hl-beauty-bar-label">美貌</span>';
    html+='<div class="hl-beauty-bar"><div class="hl-beauty-bar-fill" style="width:'+barW+'%"></div></div></div>';
    html+='<div class="hl-beauty-favor">宠爱：<span class="hl-favor-level" style="color:'+favorClr+'">'+favorNm+'</span>（'+b.favor+'/100）</div>';
    html+='<div class="hl-beauty-favor" style="font-size:10px;color:#a08060;">赎身价 <b style="color:#ffd700;">'+b.price+'</b> 两</div>';
    html+='</div>';
    html+='<div class="hl-beauty-actions">';
    html+='<button class="hl-btn-room" onclick="Game.enterHonglouRoom(\''+b.id+'\')">进入闺房</button>';
    if(extraBtns)html+=extraBtns;
    html+='</div></div>';
    return html;
  }
  function showHonglou(){
    if(state.treasury<200){showFeedback('国库空虚，无法前往醉红楼！');return;}
    var curKey=state.year*12+state.month;
    if(state.honglouLastVisitMonth && state.honglouLastVisitMonth >= curKey){showFeedback('本月已经去过醉红楼了。');return;}
    state._honglou={active:true,beauties:[],currentBeauty:null,contest:null,listenCount:0,hongCount:0,selectedForAdopt:[],oldFlames:[]};
    var hl=state._honglou;
    // 生成 3-5 位女子
    var count=rand(3,5);
    var hasQueen=Math.random()<0.3; // 30%概率有花魁
    for(var i=0;i<count;i++){
      hl.beauties.push(genHonglouBeauty(i===0&&hasQueen,false,null));
    }
    // 旧识召回
    if(state.honglouOldFlames&&state.honglouOldFlames.length>0){
      var reunionChance=0.4;
      if(Math.random()<reunionChance){
        var oldFlame=pick(state.honglouOldFlames);
        var oldSince=(state.honglouTotalVisits||0)-(oldFlame.lastVisitVisits||0);
        oldFlame.visitsSinceLastSeen=oldSince;
        var reborn=genHonglouBeauty(false,true,oldFlame);
        hl.beauties.push(reborn);
        hl.oldFlames.push(reborn);
      }
    }
    // 更新UI
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    var visitNum=state.honglouTotalVisits||0;
    document.getElementById('honglou-visit-info').textContent='第 '+visitNum+' 次来访';
    renderHonglouMain();
    document.getElementById('page-honglou').classList.add('active');
  }
  function renderHonglouMain(){
    var hl=state._honglou;
    if(!hl||!hl.active)return;
    var content=document.getElementById('honglou-content');
    var html='';
    // 老鸨
    var mamaText=pick(HL_MAMA_LINES);
    // 情报（20%概率）
    if(Math.random()<0.2){
      var intel=pick(HL_MAMA_INTEL);
      mamaText+='<br><span style="font-size:11px;color:#c0a060;">「'+intel.text+'」</span>';
    }
    html+='<div class="honglou-mama">';
    html+='<div class="honglou-mama-name">老鸨 · 金妈妈</div>';
    html+='<div class="honglou-mama-text">「'+mamaText+'」</div>';
    html+='</div>';
    // 花魁大赛（30%概率）
    var contestAvailable=Math.random()<0.3;
    if(contestAvailable){
      var coold=state.honglouContestCooldown||0;
      if(coold<=0||state.honglouTotalVisits===0)contestAvailable=true;
      else contestAvailable=false;
    }
    // 标语
    html+='<div class="honglou-slogan">「春风十里，不如红楼一醉」</div>';
    // 功能按钮
    html+='<div class="honglou-grid">';
    html+='<div class="honglou-card" onclick="Game.showHonglouListen()"><div class="honglou-card-icon">\u{1F3A4}</div><div class="honglou-card-name">听 曲 闲 谈</div><div class="honglou-card-desc">50-150两 · 琴伎歌女献艺</div></div>';
    html+='<div class="honglou-card" onclick="Game.showHonglouDance()"><div class="honglou-card-icon">\u{1F483}</div><div class="honglou-card-name">赏 舞 品 酒</div><div class="honglou-card-desc">100-300两 · 舞姬翩跹</div></div>';
    if(contestAvailable){
      html+='<div class="honglou-card" onclick="Game.showHonglouContestStart()"><div class="honglou-card-icon">\u{1F3C6}</div><div class="honglou-card-name">花 魁 大 赛</div><div class="honglou-card-desc">500两起 · 月度盛事</div></div>';
    }else{
      html+='<div class="honglou-card disabled"><div class="honglou-card-icon">\u{1F3C6}</div><div class="honglou-card-name">花 魁 大 赛</div><div class="honglou-card-desc">本月暂无举办</div></div>';
    }
    var hasOld=hl.oldFlames&&hl.oldFlames.length>0;
    html+='<div class="honglou-card'+(hasOld?'':' disabled')+'" onclick="'+(hasOld?'Game.showHonglouOldFlames()':'')+'"><div class="honglou-card-icon">\u{1F4CB}</div><div class="honglou-card-name">寻 旧 识</div><div class="honglou-card-desc">'+(hasOld?'有 '+hl.oldFlames.length+' 位旧识':'暂无旧识')+'</div></div>';
    html+='</div>';
    // 纳妾按钮
    html+='<button class="honglou-leave-btn" onclick="Game.showHonglouAdopt()" style="margin-top:12px;background:linear-gradient(180deg,rgba(180,40,40,0.5),rgba(140,30,30,0.5));color:#ffd700;border-color:rgba(255,215,0,0.3);letter-spacing:4px;">纳 妾（'+((hl.selectedForAdopt||[]).length)+'人）</button>';
    // 离开按钮
    html+='<button class="honglou-leave-btn" onclick="Game.finishHonglou()">离    开</button>';
    content.innerHTML=html;
  }
  function showHonglouListen(){
    var cost=rand(50,150);
    if(state.treasury<cost){showFeedback('银两不足！');return;}
    state.treasury-=cost;
    state._honglou.listenCount++;
    // 生成1-2位表演者
    var perfCount=Math.random()<0.5?1:2;
    var perfs=[];
    var perfTypes=['music','sing'];
    for(var i=0;i<perfCount;i++){
      var typeData=HL_TYPES.find(function(t){return t.id===perfTypes[i];});
      var b=genHonglouBeauty(false,false,null);
      b.type=typeData.id;b.typeName=typeData.name;b.typeData=typeData;
      b.personality=PERSONALITIES.find(function(p){return p.name===pick(typeData.pNames);})||PERSONALITIES[0];
      b.trait=pick(typeData.traits);
      perfs.push(b);
    }
    showHonglouPerformance(perfs,cost,'听曲闲谈');
  }
  function showHonglouDance(){
    var costs=[100,200,300];
    var cost=pick(costs);
    if(state.treasury<cost){showFeedback('银两不足！');return;}
    state.treasury-=cost;
    state._honglou.listenCount++;
    // 根据花费决定表演规模
    var perfCount=cost>=300?3:cost>=200?2:1;
    var perfs=[];
    var typeData=HL_TYPES.find(function(t){return t.id==='dance';});
    for(var i=0;i<perfCount;i++){
      var b=genHonglouBeauty(false,false,null);
      b.type='dance';b.typeName='舞姬';b.typeData=typeData;
      b.personality=PERSONALITIES.find(function(p){return p.name===pick(typeData.pNames);})||PERSONALITIES[0];
      b.trait=pick(typeData.traits);
      perfs.push(b);
    }
    showHonglouPerformance(perfs,cost,'赏舞品酒');
  }
  function showHonglouPerformance(perfs,cost,title){
    document.getElementById('honglou-perf-header').textContent=title;
    var html='<div class="hl-performance">';
    // 表演描写
    for(var i=0;i<perfs.length;i++){
      var b=perfs[i];
      var texts=HL_PERF_TEXTS[b.type]||HL_PERF_TEXTS.sing;
      var txt=pick(texts);
      html+='<div class="hl-perf-scene">'+txt.replace(/奴家/g,'<em>'+b.name+'</em>').replace(/她/g,'<em>'+b.name+'</em>')+'</div>';
      // 女子卡片
      html+='<div style="display:flex;align-items:center;padding:10px;margin:8px 0;background:rgba(60,10,10,0.4);border:1px solid rgba(218,165,32,0.2);border-radius:10px;">';
      html+=portraitHL(b,60,80);
      html+='<div style="flex:1;padding-left:10px;">';
      html+='<div style="font-size:14px;font-weight:bold;color:#ffd700;">'+b.name+'</div>';
      html+='<div style="font-size:11px;color:#b09060;">'+b.age+'岁 · '+b.typeName+' · 美貌 '+b.beauty+' · 才华 '+b.talent+'</div>';
      html+='<div style="font-size:11px;color:#a08060;font-style:italic;margin-top:4px;">「'+b.greeting+'」</div>';
      html+='</div></div>';
      if(i<perfs.length-1)html+='<div class="hl-perf-divider"></div>';
    }
    html+='<div class="hl-perf-divider"></div>';
    html+='<div style="font-size:12px;color:#a08060;text-align:center;margin-bottom:10px;">花费 '+cost+' 两</div>';
    html+='<div class="hl-perf-actions">';
    // 翻牌按钮（只对第一位或随机一位）
    var target=perfs[0];
    var flipCost=target.price>=800?500:target.price>=500?300:200;
    html+='<button class="hl-perf-btn" onclick="Game.flipHonglouPerf(\''+target.id+'\','+flipCost+')">🔥 翻牌 '+target.name+'（'+flipCost+'两）→ 闺房</button>';
    if(perfs.length>1){
      html+='<button class="hl-perf-btn secondary" onclick="Game.tipHonglouPerf(20)">打赏众人（20两）</button>';
    }
    html+='<button class="hl-perf-btn secondary" onclick="Game.closeHonglouPerformance()">只是欣赏，离开</button>';
    html+='</div></div>';
    document.getElementById('honglou-perf-content').innerHTML=html;
    // 暂存表演数据
    state._honglou._perfs=perfs;
    document.getElementById('modal-honglou-performance').classList.add('show');
  }
  function flipHonglouPerf(id,cost){
    if(state.treasury<cost){showFeedback('银两不足！');return;}
    state.treasury-=cost;
    var b=state._honglou.beauties.find(function(x){return x.id===id;});
    if(!b){
      // 表演临时生成的女子，加到beauties
      b=state._honglou._perfs.find(function(x){return x.id===id;});
      if(b)state._honglou.beauties.push(b);
    }
    if(b){b.favor=Math.min((b.favor||0)+5,100);b.favorLevel=getFavorKey(b.favor);}
    document.getElementById('modal-honglou-performance').classList.remove('show');
    closeModal();
    if(b)setTimeout(function(){enterHonglouRoom(b.id);},300);
  }
  function tipHonglouPerf(amount){
    if(state.treasury<amount){showFeedback('银两不足！');return;}
    state.treasury-=amount;
    // 所有表演女子好感+3
    var perfs=state._honglou._perfs||[];
    perfs.forEach(function(b){b.favor=Math.min((b.favor||0)+3,100);b.favorLevel=getFavorKey(b.favor);});
    showFeedback('打赏了 '+amount+' 两，众女子感激不尽。<br>好感 <span class="pos">+3</span>');
    document.getElementById('modal-honglou-performance').classList.remove('show');
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    save();
  }
  function closeHonglouPerformance(){
    document.getElementById('modal-honglou-performance').classList.remove('show');
    closeModal();
    renderHonglouMain();
  }
  function enterHonglouRoom(id){
    var hl=state._honglou;
    if(!hl||!hl.active)return;
    var b=hl.beauties.find(function(x){return x.id===id;});
    if(!b&&hl.oldFlames)b=hl.oldFlames.find(function(x){return x.id===id;});
    if(!b){showFeedback('找不到这位女子……');return;}
    hl.currentBeauty=b;
    renderHonglouRoom();
    document.getElementById('modal-honglou-room').classList.add('show');
  }
  function renderHonglouRoom(){
    var b=state._honglou.currentBeauty;
    if(!b)return;
    document.getElementById('honglou-room-header').textContent=b.name+' 的闺房';
    var hpColor=b.health>=70?'#4caf50':b.health>=40?'#ff9800':'#e55555';
    var favorClr=getFavorColor(b.favor);
    var favorNm=getFavorName(b.favor);
    var priceDiscount=calcPriceDiscount(b);
    var finalPrice=Math.round(b.price*priceDiscount);
    var canBed=b.favor>=20;
    var html='<div class="hl-room">';
    html+='<div class="hl-room-portrait">'+portraitHL(b,140,180)+'</div>';
    html+='<div class="hl-room-greeting">「'+(b.greeting?b.greeting.replace('{name}',b.name):'公子来了呀~')+'」</div>';
    html+='<div class="hl-room-stats">';
    html+='<div class="hl-room-stats-row">';
    html+='<div>美貌 <b style="color:#e06080;">'+b.beauty+'</b></div>';
    html+='<div>才华 <b style="color:#6080e0;">'+b.talent+'</b></div>';
    html+='<div>智慧 <b style="color:#40a080;">'+b.wisdom+'</b></div>';
    html+='<div>健康 <b style="color:'+hpColor+'">'+b.health+'</b></div>';
    html+='<div>性格 <b style="color:#9060c0;">'+b.personality.name+'</b></div>';
    html+='<div>特长 <b style="color:#c49030;">'+b.trait+'</b></div>';
    html+='<div>年龄 <b>'+b.age+'</b> 岁</div>';
    html+='<div>赎身价 <b style="color:#ffd700;">'+finalPrice+'</b> 两'+(priceDiscount<1?'（'+Math.round(priceDiscount*10)+'折）':'')+'</div>';
    html+='<div>好感 <span class="hl-favor-level" style="color:'+favorClr+'">'+favorNm+'</span>（'+b.favor+'/100）</div>';
    if(b.visitCount>0)html+='<div>已宠幸 <b style="color:#d06080;">'+b.visitCount+'</b> 次</div>';
    html+='</div></div>';
    // 按钮
    html+='<div class="hl-room-actions">';
    html+='<button class="hl-room-btn" onclick="Game.honglouChat()">💬 聊天</button>';
    html+='<button class="hl-room-btn" onclick="Game.honglouGift()">💰 赠礼（100两）</button>';
    html+='<button class="hl-room-btn'+(canBed?'':' disabled')+'" onclick="Game.honglouBed()">🔥 宠幸'+(b.price>=800?'300':'200')+'两'+(canBed?'':' · 需好感20+')+'</button>';
    html+='</div>';
    html+='<div class="hl-room-actions">';
    html+='<button class="hl-room-btn danger" onclick="Game.honglouAdoptOne()">🏠 纳妾（'+finalPrice+'两）</button>';
    html+='</div>';
    html+='<button class="hl-room-btn leave" onclick="Game.closeHonglouRoom()">离    开</button>';
    html+='</div>';
    document.getElementById('honglou-room-content').innerHTML=html;
  }
  function calcPriceDiscount(b){
    if(b.favorLevel==='obsessed')return 0.25;
    if(b.favorLevel==='love')return 0.5;
    if(b.favorLevel==='close')return 0.7;
    if(b.favorLevel==='familiar')return 0.9;
    return 1.0;
  }
  function closeHonglouRoom(){
    document.getElementById('modal-honglou-room').classList.remove('show');
    state._honglou.currentBeauty=null;
    closeModal();
    renderHonglouMain();
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    save();
  }
  // 聊天
  function honglouChat(){
    var b=state._honglou.currentBeauty;
    if(!b)return;
    var lines=HL_CHAT_LINES[b.personality.name]||HL_CHAT_LINES.温婉;
    var line=pick(lines);
    var favorGain=rand(3,8);
    b.favor=Math.min(b.favor+favorGain,100);
    b.favorLevel=getFavorKey(b.favor);
    // 10%概率获得情报
    var intelHtml='';
    if(Math.random()<0.1){
      var intel=pick(HL_MAMA_INTEL);
      intelHtml='<div class="hl-dialogue" style="border-left-color:#c0a060;"><div class="hl-dialogue-speaker">📜 暗传情报</div>'+intel.text+'</div>';
    }
    // 15%概率提起身世
    var lifeHtml='';
    if(Math.random()<0.15){
      lifeHtml='<div class="hl-dialogue"><div class="hl-dialogue-speaker">'+b.name+'</div>奴家原是'+pick(['江南','蜀中','中原','塞外'])+'人氏，因家中'+pick(['遭了变故','欠了债务','被人所逼','遭人陷害'])+'，才流落至此……</div>';
      b.favor=Math.min(b.favor+2,100);
    }
    var html='<div style="padding:16px;">';
    html+='<div class="hl-dialogue"><div class="hl-dialogue-speaker">'+b.name+'</div>'+line+'</div>';
    html+=lifeHtml+intelHtml;
    html+='<div style="text-align:center;font-size:12px;color:#a0c0a0;margin:8px 0;">好感 <span class="pos">+'+favorGain+'</span></div>';
    html+='<div class="hl-chat-options">';
    html+='<button class="hl-chat-opt" onclick="Game.honglouChatReply(1)">「你不必难过，以后有我在。」（好感+3）</button>';
    html+='<button class="hl-chat-opt" onclick="Game.honglouChatReply(2)">「改日我带你出去走走。」（好感+5）</button>';
    html+='<button class="hl-chat-opt" onclick="Game.honglouChatReply(0)">「嗯，知道了。」（结束聊天）</button>';
    html+='</div></div>';
    document.getElementById('honglou-dialogue-content').innerHTML=html;
    document.getElementById('modal-honglou-dialogue').classList.add('show');
  }
  function honglouChatReply(opt){
    var b=state._honglou.currentBeauty;
    if(!b)return;
    if(opt===1)b.favor=Math.min(b.favor+3,100);
    else if(opt===2)b.favor=Math.min(b.favor+5,100);
    b.favorLevel=getFavorKey(b.favor);
    document.getElementById('modal-honglou-dialogue').classList.remove('show');
    closeModal();
    renderHonglouRoom();
    save();
  }
  function closeHonglouDialogue(){
    document.getElementById('modal-honglou-dialogue').classList.remove('show');
    closeModal();
  }
  // 赠礼
  function honglouGift(){
    var b=state._honglou.currentBeauty;
    if(!b)return;
    if(state.treasury<100){showFeedback('银两不足！');return;}
    state.treasury-=100;
    var gifts=[
      {icon:'\u{1F48E}',name:'珍珠钗'},
      {icon:'\u{1F3A8}',name:'团扇一把'},
      {icon:'\u{1F338}',name:'胭脂一盒'},
      {icon:'\u{1F4D6}',name:'诗集一卷'},
    ];
    var gift=pick(gifts);
    var favorGain=rand(10,20);
    b.favor=Math.min(b.favor+favorGain,100);
    b.favorLevel=getFavorKey(b.favor);
    showFeedback(b.name+' 接过'+gift.icon+gift.name+'，欢喜不已。<br>好感 <span class="pos">+'+favorGain+'</span>');
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    renderHonglouRoom();
    save();
  }
  // 宠幸
  function honglouBed(){
    var b=state._honglou.currentBeauty;
    if(!b)return;
    if(b.favor<20){showFeedback('她还对你有些生分，先多聊聊吧。');return;}
    var bedCost=b.price>=800?300:200;
    if(state.treasury<bedCost){showFeedback('银两不足！');return;}
    state.treasury-=bedCost;
    // 宠幸剧情
    var pName=b.personality.name;
    var bedTexts=HL_BED_TEXTS[pName]||HL_BED_TEXTS.温婉;
    // 如果没有对应性格的文本，用温婉的
    if(!HL_BED_TEXTS[pName])bedTexts=HL_BED_TEXTS.温婉;
    var html='<div style="padding:16px;">';
    html+='<div class="hl-reunion-scene">';
    html+=bedTexts[0].replace(/{name}/g,b.name)+'</div>';
    html+='<div class="hl-dialogue"><div class="hl-dialogue-speaker">'+b.name+'</div>'+bedTexts[1]+'</div>';
    html+='<div class="hl-reunion-scene">'+bedTexts[2].replace(/{name}/g,b.name)+'</div>';
    html+='</div>';
    document.getElementById('honglou-bed-header').textContent='💕 '+b.name;
    document.getElementById('honglou-bed-content').innerHTML=html;
    document.getElementById('modal-honglou-bed').classList.add('show');
    // 结算
    var favorGain=rand(15,25);
    b.favor=Math.min(b.favor+favorGain,100);
    b.favorLevel=getFavorKey(b.favor);
    b.visitCount=(b.visitCount||0)+1;
    // 怀孕判定
    var pregRate=0.10;
    pregRate+=(b.favor/10)*0.015; // 好感加成
    if(b.favor>80)pregRate+=0.05;
    if(b.age<18)pregRate+=0.02;
    if(b.age>22)pregRate-=0.01;
    if(b.type==='dance'||b.type==='sing')pregRate+=0.03;
    pregRate+=(b.visitCount||0)*0.02;
    pregRate=Math.min(pregRate,0.25);
    var isPreg=Math.random()<pregRate;
    // 关闭弹窗
    var self=this;
    setTimeout(function(){
      document.getElementById('modal-honglou-bed').classList.remove('show');
      closeModal();
      var msg='宠幸了 <span class="pos">'+b.name+'</span><br>';
      msg+='好感 <span class="pos">+'+favorGain+'</span>（当前 '+b.favor+'，'+getFavorName(b.favor)+'）<br>';
      msg+='国库 <span class="neg">-'+bedCost+'</span> 两';
      if(isPreg){
        // 记录怀孕
        var childGender=Math.random()<0.5?'male':'female';
        var genderText=childGender==='male'?'皇子':'皇女';
        var childName=genChildName(b.name);
        if(!state.honglouPregnancies)state.honglouPregnancies=[];
        state.honglouPregnancies.push({
          beautyId:b.id,beautyName:b.name,beautyData:{name:b.name,type:b.type,portraitIdx:b.portraitIdx,portraitSeed:b.portraitSeed,personality:{name:b.personality.name},trait:b.trait},
          pregFrom:state.year*12+state.month,revealed:false,decision:null,childGender:childGender,childName:childName,childAge:0,reunionType:'baby',
        });
        msg+='<br><span style="font-size:11px;color:#d06080;">（她似乎有了……但你还不知道）</span>';
      }
      showFeedback(msg);
      document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
      renderHonglouRoom();
      save();
    },2000);
  }
  function closeHonglouBed(){
    document.getElementById('modal-honglou-bed').classList.remove('show');
    closeModal();
  }
  function genChildName(motherName){
    var boyNames=['承欢','承恩','承泽','承佑','承安','承平','承业','承望','承德','承志'];
    var girlNames=['婉儿','灵儿','月儿','萱儿','瑶儿','琪儿','琳儿','璐儿','瑾儿','瑗儿'];
    if(Math.random()<0.5)return pick(boyNames);
    return pick(girlNames);
  }
  // 旧识
