  // 纳妾（从主界面选择）
  function showHonglouAdopt(){
    var hl=state._honglou;
    if(!hl||!hl.active)return;
    // 只显示宠爱度达到"熟络"以上的
    var available=hl.beauties.filter(function(b){return b.favor>=40;});
    if(available.length===0){showFeedback('没有宠爱度足够的女子，需要先增进感情才行。');return;}
    hl.selectedForAdopt=[];
    var html='<div class="hl-adopt-list">';
    html+='<div style="text-align:center;font-size:14px;color:#ffd700;margin-bottom:12px;">选 择 纳 妾 的 女 子</div>';
    available.forEach(function(b,i){
      var disc=calcPriceDiscount(b);
      var finalPrice=Math.round(b.price*disc);
      html+='<div class="hl-adopt-item">';
      html+='<input type="checkbox" class="hl-adopt-check" id="hl-adopt-'+i+'" onchange="Game.updateHonglouAdoptTotal()" data-idx="'+i+'" data-price="'+finalPrice+'">';
      html+='<div class="hl-adopt-info">';
      html+='<div class="hl-adopt-name">'+b.name+'</div>';
      html+='<div class="hl-adopt-price">'+b.typeName+' · '+getFavorName(b.favor)+' · 赎身价 '+finalPrice+'两';
      if(disc<1)html+='（'+Math.round(disc*10)+'折）';
      html+='</div></div></div>';
    });
    html+='<div class="hl-adopt-total" id="hl-adopt-total">共 0 人，总计 0 两</div>';
    html+='<div style="display:flex;gap:8px;padding:0 16px 16px;">';
    html+='<button class="btn-primary" onclick="Game.confirmHonglouAdopt()" style="flex:1;">确认纳妾</button>';
    html+='<button class="btn-primary" onclick="Game.closeHonglouAdopt()" style="flex:1;background:rgba(160,128,96,0.1);border-color:rgba(160,128,96,0.2);color:#a08060;">取消</button>';
    html+='</div></div>';
    document.getElementById('honglou-adopt-content').innerHTML=html;
    document.getElementById('modal-honglou-adopt').classList.add('show');
  }
  function updateHonglouAdoptTotal(){
    var checks=document.querySelectorAll('.hl-adopt-check:checked');
    var total=0;
    checks.forEach(function(c){total+=parseInt(c.getAttribute('data-price'));});
    document.getElementById('hl-adopt-total').textContent='共 '+checks.length+' 人，总计 '+total+' 两';
  }
  function confirmHonglouAdopt(){
    var checks=document.querySelectorAll('.hl-adopt-check:checked');
    if(checks.length===0){showFeedback('请选择要纳妾的女子。');return;}
    var hl=state._honglou;
    var totalPrice=0;
    var selected=[];
    checks.forEach(function(c){
      var idx=parseInt(c.getAttribute('data-idx'));
      var b=hl.beauties.filter(function(x){return x.favor>=40;})[idx];
      if(b){totalPrice+=parseInt(c.getAttribute('data-price'));selected.push(b);}
    });
    if(state.treasury<totalPrice){showFeedback('银两不足，需要 '+totalPrice+' 两！');return;}
    var remain=30-state.concubines.length;
    if(selected.length>remain){showFeedback('后宫只剩 '+remain+' 个名额，最多只能选 '+remain+' 人！');return;}
    state.treasury-=totalPrice;
    var names=[];
    selected.forEach(function(b){
      var disc=calcPriceDiscount(b);
      var finalPrice=Math.round(b.price*disc);
      var initRank=b.beauty>=85&&b.talent>=70?'贵人':b.beauty>=70?'常在':'答应';
      if(b.favorLevel==='obsessed')initRank=RANKS[Math.max(0,RANKS.indexOf(initRank)-1)]||initRank;
      var concubine={id:genId(),name:b.name,age:b.age,beauty:b.beauty,talent:b.talent,wisdom:b.wisdom,health:b.health,favor:Math.round(b.beauty*1.5),power:rand(5,20),rank:initRank,personality:b.personality,trait:b.trait,family:{name:'醉红楼',initRank:initRank,color:'#c49030'},pregnant:false,pregMonth:0,portraitIdx:b.portraitIdx,title:'',fromHonglou:true,honglouSkill:b.type,portraitSeed:b.portraitSeed,stress:0,stressCap:getStressCap(b.personality.name),behaviorLog:[],_favored:false,favors:{},grudge:null,_flatterCount:0};
      state.concubines.push(concubine);
      names.push(b.name);
      logEvent('醉红楼',b.name+' 赎身入宫，封为 '+initRank);
      // 从beauties移除
      hl.beauties=hl.beauties.filter(function(x){return x.id!==b.id;});
      if(hl.oldFlames)hl.oldFlames=hl.oldFlames.filter(function(x){return x.id!==b.id;});
    });
    save();updateUI();
    document.getElementById('modal-honglou-adopt').classList.remove('show');
    closeModal();
    showFeedback('<span class="pos">'+names.join('、')+'</span> 已赎身入宫<br>国库 <span class="neg">-'+totalPrice+'</span> 两');
    renderHonglouMain();
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
  }
  function closeHonglouAdopt(){
    document.getElementById('modal-honglou-adopt').classList.remove('show');
    closeModal();
  }
