  // 花魁大赛
  function showHonglouContestStart(){
    if(state.treasury<500){showFeedback('银两不足，花魁大赛需要500两！');return;}
    state.treasury-=500;
    var hl=state._honglou;
    // 生成5位参赛女子
    hl.contest={active:true,contestants:[],round:0,playerInvested:{}};
    for(var i=0;i<5;i++){
      var b=genHonglouBeauty(i===0,true,null);
      b.contestScore=rand(60,85);
      hl.contest.contestants.push(b);
      if(!hl.beauties.some(function(x){return x.id===b.id;}))hl.beauties.push(b);
    }
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    renderHonglouContestRound();
    document.getElementById('modal-honglou-contest').classList.add('show');
  }
