  function contestNotice(idx){
    var b=state._honglou.contest.contestants[idx];
    if(!b)return;
    b.contestScore+=5;
    b.favor=Math.min((b.favor||0)+5,100);
    b.favorLevel=getFavorKey(b.favor);
    showFeedback('多看了'+b.name+'一眼，她脸颊微红，更加卖力表演了。<br>得分 <span class="pos">+5</span>，好感 <span class="pos">+5</span>');
  }
  function contestInvest(id,amount){
    if(state.treasury<amount){showFeedback('银两不足！');return;}
    state.treasury-=amount;
    var b=state._honglou.contest.contestants.find(function(x){return x.id===id;});
    if(b){
      b.contestScore+=20;
      if(!state._honglou.contest.playerInvested[id])state._honglou.contest.playerInvested[id]=0;
      state._honglou.contest.playerInvested[id]+=amount;
      showFeedback('为 '+b.name+' 掷千金 '+amount+' 两！<br>得分 <span class="pos">+20</span>');
    }
    document.getElementById('honglou-treasury-info').textContent='国库：'+state.treasury+' 两';
    renderHonglouContestRound();
    save();
  }
  function contestNextRound(){
    state._honglou.contest.round++;
    if(state._honglou.contest.round>=3){renderHonglouContestRound();return;}
    renderHonglouContestRound();
  }
  function contestSolo(id){
    var b=state._honglou.contest.contestants.find(function(x){return x.id===id;});
    if(!b)return;
    var cost=Math.round(b.price*1.5);
    if(state.treasury<cost){showFeedback('银两不足！');return;}
    state.treasury-=cost;
    b.favor=75;b.favorLevel='love';
    document.getElementById('modal-honglou-contest').classList.remove('show');
    closeModal();
    enterHonglouRoom(b.id);
  }
