  function closeHonglouContest(){
    document.getElementById('modal-honglou-contest').classList.remove('show');
    state._honglou.contest=null;
    closeModal();
  }
  // 离开醉红楼
  function finishHonglou(){
    var hl=state._honglou;
    if(!hl||!hl.active)return;
    // 保存旧识
    if(!state.honglouOldFlames)state.honglouOldFlames=[];
    hl.beauties.forEach(function(b){
      if(b.visitCount>0){
        var keepRate=b.favorLevel==='obsessed'?1.0:b.favorLevel==='love'?0.8:0.4;
        if(Math.random()<keepRate){
          state.honglouOldFlames.push({id:b.id,name:b.name,type:b.type,portraitIdx:b.portraitIdx,portraitSeed:b.portraitSeed,favor:b.favor,visitCount:b.visitCount,personality:{name:b.personality.name},trait:b.trait,price:b.price,typeName:b.typeName,isFlowerQueen:b.isFlowerQueen,lastVisitVisits:state.honglouTotalVisits||0,age:b.age,beauty:b.beauty,talent:b.talent,wisdom:b.wisdom,health:b.health,greeting:b.greeting});
        }
      }
    });
    // 记录访问信息
    state.honglouTotalVisits=(state.honglouTotalVisits||0)+1;
    state.honglouLastVisitMonth=state.year*12+state.month;
    state.honglouLastVisitYear=state.year;
    // 花魁大赛冷却
    state.honglouContestCooldown=(state.honglouContestCooldown||0)+1;
    // 风险判定
    triggerHonglouRisk();
    // 清理
    state._honglou.active=false;
    state._honglou=null;
    // 关闭页面
    document.getElementById('page-honglou').classList.remove('active');
    save();
  }
  // 风险判定
  function triggerHonglouRisk(){
    if(Math.random()>=0.3)return;
    var hasQueen=state.concubines.some(function(c){return c.rank==='皇后';});
    if(hasQueen&&Math.random()<0.5){
      showHonglouEvent('皇后得知',[
        {text:'去坤宁宫安抚（200两）',effect:function(){
          var q=state.concubines.find(function(c){return c.rank==='皇后';});
          if(q){q.favor=clamp(q.favor-10,0,2200);if(state.treasury>=200)state.treasury-=200;}
          showFeedback('皇上亲自去坤宁宫安抚皇后。<br>皇后宠爱 <span class="neg">-10</span>，国库 <span class="neg">-200</span>');
        }},
        {text:'不去管她',effect:function(){
          var q=state.concubines.find(function(c){return c.rank==='皇后';});
          if(q)q.favor=clamp(q.favor-20,0,2200);
          showFeedback('皇后愈发伤心。<br>皇后宠爱 <span class="neg">-20</span>');
        }},
      ]);
    }else{
      showHonglouEvent('御史弹劾',[
        {text:'置之不理',effect:function(){
          showFeedback('置之不理，朝野议论纷纷。<br>声望有所下降。');
          logEvent('醉红楼','御史弹劾，皇上置之不理');
        }},
        {text:'贬官压制（500两）',effect:function(){
          if(state.treasury>=500){state.treasury-=500;showFeedback('贬了御史的官，平息了风波。<br>国库 <span class="neg">-500</span> 两');}
          else{showFeedback('国库空虚，拿不出500两……<br>只能置之不理了。');}
          logEvent('醉红楼','皇上贬官压制');
        }},
        {text:'下罪己诏',effect:function(){
          showFeedback('皇上自省，下月行动力 <span class="neg">-1</span>，但朝野渐渐平息。');
          logEvent('醉红楼','皇上罪己诏');
        }},
      ]);
    }
  }
